1	//! Structured event logging for bivvy sessions.
2	//!
3	//! Records every event during a bivvy session as a JSONL (JSON Lines) entry.
4	//! One file per session. Logs are stored in `~/.bivvy/logs/` with automatic
5	//! retention management (age + size limits).
6	//!
7	//! # Architecture
8	//!
9	//! The event logger is one of three independent event consumers:
10	//!
11	//! 1. **Event logger** (this module) — writes all events to JSONL for
12	//!    debugging, feedback, and auditing
13	//! 2. **State recorder** — updates persistent state on step completion
14	//! 3. **Presenter** — shows real-time terminal output
15	//!
16	//! Each consumer handles only the events it cares about. They don't know
17	//! about each other.
18	//!
19	//! # Log Format
20	//!
21	//! Each line is a JSON object with:
22	//! - `ts` — ISO 8601 timestamp with milliseconds
23	//! - `session` — unique session ID
24	//! - `event` — the event data (tagged by `type`)
25	//!
26	//! # Retention
27	//!
28	//! Logs expire automatically. Default: 30 days or 500 MB total, whichever
29	//! comes first. Cleanup runs at the start of each session.
30	
31	pub mod bus;
32	pub mod events;
33	
34	pub use bus::EventBus;
35	pub use events::{
36	    BehaviorFlags, BivvyEvent, DecisionTrace, DependencyStatus, EventConsumer, FilterResult,
37	    InputMethod, NamedCheckResult, RequirementGapInfo, RerunInfo, SatisfactionResult,
38	    StepOutcomeKind, TraceCheckResult,
39	};
40	
41	use std::fs::{self, File};
42	use std::io::{BufWriter, Write};
43	use std::path::{Path, PathBuf};
44	
45	use chrono::Utc;
46	use serde::Serialize;
47	
48	/// Default log retention: 30 days.
49	pub const DEFAULT_RETENTION_DAYS: u32 = 30;
50	
51	/// Default log retention: 500 MB.
52	pub const DEFAULT_RETENTION_MB: u64 = 500;
53	
54	/// Get the default log directory path.
55	///
56	/// Returns `~/.bivvy/logs/`.
57	pub fn default_log_dir() -> PathBuf {
58	    crate::sys::home_dir()
59	        .unwrap_or_else(|| PathBuf::from("~"))
60	        .join(".bivvy")
61	        .join("logs")
62	}
63	
64	/// Extract the `working_directory` recorded in a log file's
65	/// `session_started` event.
66	///
67	/// Returns `None` if the file cannot be read, contains no `session_started`
68	/// event, or that event does not carry a `working_directory` field. Used by
69	/// `bivvy last` and `bivvy history` to scope log scanning to the current
70	/// project.
71	pub fn log_working_directory(log_path: &Path) -> Option<PathBuf> {
72	    let content = std::fs::read_to_string(log_path).ok()?;
73	    for line in content.lines() {
74	        let value: serde_json::Value = match serde_json::from_str(line) {
75	            Ok(v) => v,
76	            Err(_) => continue,
77	        };
78	        if value.get("type").and_then(|t| t.as_str()) == Some("session_started") {
79	            return value
80	                .get("working_directory")
81	                .and_then(|w| w.as_str())
82	                .map(PathBuf::from);
83	        }
84	    }
85	    None
86	}
87	
88	/// List all JSONL log files in `log_dir` that belong to `canonical_project`.
89	///
90	/// Order is unspecified. Returns an empty vector if the directory does not
91	/// exist or cannot be read. Used by `bivvy history --clear` to enumerate
92	/// the files that should be deleted for the current project, leaving logs
93	/// from other projects untouched.
94	pub fn list_project_logs(log_dir: &Path, canonical_project: &Path) -> Vec<PathBuf> {
95	    if !log_dir.exists() {
96	        return Vec::new();
97	    }
98	    fs::read_dir(log_dir)
99	        .ok()
100	        .into_iter()
101	        .flatten()
102	        .filter_map(|e| e.ok())
103	        .map(|e| e.path())
104	        .filter(|p| p.extension().is_some_and(|ext| ext == "jsonl"))
105	        .filter(|p| log_belongs_to_project(p, canonical_project))
106	        .collect()
107	}
108	
109	/// Test whether a log file belongs to the project rooted at `canonical_project`.
110	///
111	/// Compares the canonical project path against the `working_directory`
112	/// recorded in the log's `session_started` event. Falls back to a literal
113	/// path comparison when the recorded directory no longer exists (e.g. logs
114	/// from temp-dir tests or moved projects).
115	pub fn log_belongs_to_project(log_path: &Path, canonical_project: &Path) -> bool {
116	    let wd = match log_working_directory(log_path) {
117	        Some(p) => p,
118	        None => return false,
119	    };
120	    if wd == canonical_project {
121	        return true;
122	    }
123	    matches!(wd.canonicalize(), Ok(canon) if canon == canonical_project)
124	}
125	
126	/// A single JSONL log entry.
127	#[derive(Debug, Serialize)]
128	struct LogEntry<'a> {
129	    /// ISO 8601 timestamp with milliseconds.
130	    ts: String,
131	    /// Session ID.
132	    session: &'a str,
133	    /// The event data.
134	    #[serde(flatten)]
135	    event: &'a BivvyEvent,
136	}
137	
138	/// Retention policy for log files.
139	#[derive(Debug, Clone)]
140	pub struct RetentionPolicy {
141	    /// Maximum age in days. Files older than this are deleted.
142	    pub max_age_days: u32,
143	    /// Maximum total size in megabytes. Oldest files are deleted first
144	    /// when the total exceeds this.
145	    pub max_size_mb: u64,
146	}
147	
148	impl Default for RetentionPolicy {
149	    fn default() -> Self {
150	        Self {
151	            max_age_days: DEFAULT_RETENTION_DAYS,
152	            max_size_mb: DEFAULT_RETENTION_MB,
153	        }
154	    }
155	}
156	
157	/// Structured event logger that writes JSONL to disk.
158	///
159	/// Created at the start of every bivvy session. Writes synchronously
160	/// (the overhead of one JSON line per event is negligible). The file
161	/// is flushed when [`EventLogger::flush`] is called or on drop.
162	///
163	/// Steps marked `sensitive: true` have their command and output lines
164	/// redacted in the log (replaced with `"[SENSITIVE]"` and `"[REDACTED]"`).
165	///
166	/// # Usage
167	///
168	/// ```no_run
169	/// use bivvy::logging::{EventLogger, BivvyEvent, RetentionPolicy};
170	///
171	/// let logger = EventLogger::new(
172	///     "/tmp/bivvy-logs",
173	///     "sess_123_abc",
174	///     RetentionPolicy::default(),
175	/// ).unwrap();
176	/// ```
177	pub struct EventLogger {
178	    writer: BufWriter<File>,
179	    session_id: String,
180	    log_path: PathBuf,
181	    /// Step names that are marked `sensitive: true` in the config.
182	    /// Events for these steps have their content redacted.
183	    sensitive_steps: std::collections::HashSet<String>,
184	}
185	
186	impl EventLogger {
187	    /// Create a new event logger for a session.
188	    ///
189	    /// Creates the log directory if needed, runs retention cleanup, and
190	    /// opens a new JSONL file for this session.
191	    ///
192	    /// The log file is named `{timestamp}_{session_suffix}.jsonl` where
193	    /// the timestamp is ISO 8601 (with dashes instead of colons for
194	    /// filesystem compatibility) and the session suffix provides uniqueness.
195	    pub fn new(
196	        log_dir: impl AsRef<Path>,
197	        session_id: &str,
198	        retention: RetentionPolicy,
199	    ) -> std::io::Result<Self> {
200	        let log_dir = log_dir.as_ref();
201	        fs::create_dir_all(log_dir)?;
202	
203	        // Run retention cleanup before starting the new session
204	        if let Err(e) = cleanup_logs(log_dir, &retention) {
205	            tracing::debug!("Log retention cleanup failed: {}", e);
206	        }
207	
208	        // Generate filename: 2026-04-25T10-00-00_{session_suffix}.jsonl
209	        let now = Utc::now();
210	        let timestamp = now.format("%Y-%m-%dT%H-%M-%S").to_string();
211	
212	        // Extract a short suffix from the session ID for uniqueness
213	        let suffix = session_id
214	            .strip_prefix("sess_")
215	            .and_then(|s| s.rsplit('_').next())
216	            .unwrap_or(session_id);
217	        let filename = format!("{}_{}.jsonl", timestamp, suffix);
218	        let log_path = log_dir.join(&filename);
219	
220	        let file = File::create(&log_path)?;
221	        let writer = BufWriter::new(file);
222	
223	        Ok(Self {
224	            writer,
225	            session_id: session_id.to_string(),
226	            log_path,
227	            sensitive_steps: std::collections::HashSet::new(),
228	        })
229	    }
230	
231	    /// Returns the path to the log file.
232	    pub fn log_path(&self) -> &Path {
233	        &self.log_path
234	    }
235	
236	    /// Register step names that should have their content redacted in logs.
237	    ///
238	    /// Call this after loading the config, before any events are emitted.
239	    pub fn set_sensitive_steps(&mut self, steps: impl IntoIterator<Item = String>) {
240	        self.sensitive_steps = steps.into_iter().collect();
241	    }
242	
243	    /// Flush the log buffer to disk.
244	    pub fn flush(&mut self) -> std::io::Result<()> {
245	        self.writer.flush()
246	    }
247	
248	    /// Returns true if the given step name is marked sensitive.
249	    fn is_sensitive(&self, step_name: &str) -> bool {
250	        self.sensitive_steps.contains(step_name)
251	    }
252	
253	    /// Redact sensitive content in an event, returning a new event if
254	    /// redaction was needed or None if the event can be logged as-is.
255	    fn redact_event(&self, event: &BivvyEvent) -> Option<BivvyEvent> {
256	        match event {
257	            BivvyEvent::StepOutput { name, stream, .. } if self.is_sensitive(name) => {
258	                Some(BivvyEvent::StepOutput {
259	                    name: name.clone(),
260	                    stream: stream.clone(),
261	                    line: "[REDACTED]".to_string(),
262	                })
263	            }
264	            BivvyEvent::StepCompleted {
265	                name,
266	                success,
267	                exit_code,
268	                duration_ms,
269	                error,
270	            } if self.is_sensitive(name) => Some(BivvyEvent::StepCompleted {
271	                name: name.clone(),
272	                success: *success,
273	                exit_code: *exit_code,
274	                duration_ms: *duration_ms,
275	                error: error.as_ref().map(|_| "[REDACTED]".to_string()),
276	            }),
277	            BivvyEvent::RecoveryStarted { step, .. } if self.is_sensitive(step) => {
278	                Some(BivvyEvent::RecoveryStarted {
279	                    step: step.clone(),
280	                    error: "[REDACTED]".to_string(),
281	                })
282	            }
283	            BivvyEvent::RecoveryActionTaken {
284	                step,
285	                action,
286	                command,
287	            } if self.is_sensitive(step) => Some(BivvyEvent::RecoveryActionTaken {
288	                step: step.clone(),
289	                action: action.clone(),
290	                command: command.as_ref().map(|_| "[SENSITIVE]".to_string()),
291	            }),
292	            _ => None,
293	        }
294	    }
295	
296	    /// Write a single event as a JSONL line.
297	    fn write_event(&mut self, event: &BivvyEvent) {
298	        let entry = LogEntry {
299	            ts: Utc::now().format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string(),
300	            session: &self.session_id,
301	            event,
302	        };
303	
304	        // Write JSON + newline. Errors are logged but don't propagate —
305	        // logging failures should never break the main workflow.
306	        if let Err(e) = serde_json::to_writer(&mut self.writer, &entry) {
307	            tracing::debug!("Failed to write event to log: {}", e);
308	            return;
309	        }
310	        if let Err(e) = writeln!(self.writer) {
311	            tracing::debug!("Failed to write newline to log: {}", e);
312	        }
313	    }
314	}
315	
316	impl EventConsumer for EventLogger {
317	    fn on_event(&mut self, event: &BivvyEvent) {
318	        if let Some(redacted) = self.redact_event(event) {
319	            self.write_event(&redacted);
320	        } else {
321	            self.write_event(event);
322	        }
323	    }
324	}
325	
326	impl Drop for EventLogger {
327	    fn drop(&mut self) {
328	        let _ = self.flush();
329	    }
330	}
331	
332	/// Clean up expired log files based on the retention policy.
333	///
334	/// Deletes files that are:
335	/// 1. Older than `max_age_days`
336	/// 2. Excess files when total size exceeds `max_size_mb` (oldest first)
337	///
338	/// Only targets `.jsonl` files in the log directory.
339	pub fn cleanup_logs(log_dir: &Path, policy: &RetentionPolicy) -> std::io::Result<()> {
340	    if !log_dir.exists() {
341	        return Ok(());
342	    }
343	
344	    let max_age = chrono::Duration::days(i64::from(policy.max_age_days));
345	    let max_bytes = policy.max_size_mb * 1024 * 1024;
346	    let now = Utc::now();
347	
348	    // Collect all .jsonl files with their metadata
349	    let mut log_files: Vec<(PathBuf, fs::Metadata)> = Vec::new();
350	    for entry in fs::read_dir(log_dir)? {
351	        let entry = entry?;
352	        let path = entry.path();
353	        if path.extension().is_some_and(|ext| ext == "jsonl") {
354	            if let Ok(meta) = entry.metadata() {
355	                log_files.push((path, meta));
356	            }
357	        }
358	    }
359	
360	    // Phase 1: Delete files older than max_age_days
361	    let mut remaining: Vec<(PathBuf, u64)> = Vec::new();
362	    for (path, meta) in &log_files {
363	        let modified = meta
364	            .modified()
365	            .ok()
366	            .and_then(|t| chrono::DateTime::<Utc>::from(t).into());
367	
368	        let is_expired = modified
369	            .map(|m: chrono::DateTime<Utc>| now.signed_duration_since(m) > max_age)
370	            .unwrap_or(false);
371	
372	        if is_expired {
373	            tracing::debug!("Deleting expired log: {}", path.display());
374	            let _ = fs::remove_file(path);
375	        } else {
376	            remaining.push((path.clone(), meta.len()));
377	        }
378	    }
379	
380	    // Phase 2: If total size exceeds limit, delete oldest files first
381	    let total_size: u64 = remaining.iter().map(|(_, size)| size).sum();
382	    if total_size > max_bytes {
383	        // Sort by modification time (oldest first)
384	        remaining.sort_by(|(a, _), (b, _)| {
385	            let a_time = fs::metadata(a).and_then(|m| m.modified()).ok();
386	            let b_time = fs::metadata(b).and_then(|m| m.modified()).ok();
387	            a_time.cmp(&b_time)
388	        });
389	
390	        let mut current_size = total_size;
391	        for (path, size) in &remaining {
392	            if current_size <= max_bytes {
393	                break;
394	            }
395	            tracing::debug!(
396	                "Deleting log for size limit ({} MB > {} MB): {}",
397	                current_size / (1024 * 1024),
398	                policy.max_size_mb,
399	                path.display()
400	            );
401	            if fs::remove_file(path).is_ok() {
402	                current_size = current_size.saturating_sub(*size);
403	            }
404	        }
405	    }
406	
407	    Ok(())
408	}
