1	//! Trust verification for remote extends URLs.
2	//!
3	//! This module provides a trust store that tracks which remote URLs
4	//! have been explicitly approved by the user. When a config uses
5	//! `extends:` with a remote URL, the trust store is checked before
6	//! fetching. Untrusted URLs require user confirmation (or the
7	//! `--trust` CLI flag).
8	//!
9	//! Trusted URLs are persisted in `~/.bivvy/trusted_urls.yml`.
10	
11	use anyhow::Result;
12	use serde::{Deserialize, Serialize};
13	use std::collections::HashSet;
14	use std::fs;
15	use std::path::PathBuf;
16	
17	/// Persistent store of trusted remote extends URLs.
18	#[derive(Debug, Clone, Default, Serialize, Deserialize)]
19	pub struct TrustStore {
20	    /// Set of URLs the user has explicitly trusted.
21	    #[serde(default)]
22	    pub urls: HashSet<String>,
23	}
24	
25	impl TrustStore {
26	    /// Get the default path for the trust store file.
27	    pub fn default_path() -> PathBuf {
28	        crate::sys::home_dir()
29	            .unwrap_or_else(|| PathBuf::from("~"))
30	            .join(".bivvy")
31	            .join("trusted_urls.yml")
32	    }
33	
34	    /// Load trusted URLs from the given path.
35	    pub fn load(path: &std::path::Path) -> Result<Self> {
36	        if !path.exists() {
37	            return Ok(Self::default());
38	        }
39	
40	        let content = fs::read_to_string(path)?;
41	        let store: Self = serde_yaml::from_str(&content)?;
42	        Ok(store)
43	    }
44	
45	    /// Load from the default path.
46	    pub fn load_default() -> Result<Self> {
47	        Self::load(&Self::default_path())
48	    }
49	
50	    /// Save trusted URLs to the given path.
51	    pub fn save(&self, path: &std::path::Path) -> Result<()> {
52	        if let Some(parent) = path.parent() {
53	            fs::create_dir_all(parent)?;
54	        }
55	
56	        let content = serde_yaml::to_string(self)?;
57	
58	        // Atomic write
59	        let temp_path = path.with_extension("yml.tmp");
60	        fs::write(&temp_path, &content)?;
61	        fs::rename(&temp_path, path)?;
62	
63	        Ok(())
64	    }
65	
66	    /// Save to the default path.
67	    pub fn save_default(&self) -> Result<()> {
68	        self.save(&Self::default_path())
69	    }
70	
71	    /// Check if a URL is trusted.
72	    pub fn is_trusted(&self, url: &str) -> bool {
73	        self.urls.contains(url)
74	    }
75	
76	    /// Add a URL to the trusted set.
77	    pub fn trust(&mut self, url: &str) {
78	        self.urls.insert(url.to_string());
79	    }
80	
81	    /// Remove a URL from the trusted set.
82	    pub fn revoke(&mut self, url: &str) {
83	        self.urls.remove(url);
84	    }
85	}
86	
87	/// Policy for how to handle untrusted URLs.
88	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
89	pub enum TrustPolicy {
90	    /// Prompt the user for each untrusted URL (interactive mode).
91	    Prompt,
92	    /// Automatically trust all URLs (--trust flag).
93	    TrustAll,
94	    /// Reject untrusted URLs with an error (non-interactive mode).
95	    Reject,
96	}
97	
98	#[cfg(test)]
99	mod tests {
100	    use super::*;
101	    use tempfile::TempDir;
102	
103	    #[test]
104	    fn trust_store_default_is_empty() {
105	        let store = TrustStore::default();
106	        assert!(store.urls.is_empty());
107	    }
108	
109	    #[test]
110	    fn trust_and_check() {
111	        let mut store = TrustStore::default();
112	        let url = "https://example.com/config.yml";
113	
114	        assert!(!store.is_trusted(url));
115	        store.trust(url);
116	        assert!(store.is_trusted(url));
117	    }
118	
119	    #[test]
120	    fn revoke_removes_trust() {
121	        let mut store = TrustStore::default();
122	        let url = "https://example.com/config.yml";
123	
124	        store.trust(url);
125	        assert!(store.is_trusted(url));
126	
127	        store.revoke(url);
128	        assert!(!store.is_trusted(url));
129	    }
130	
131	    #[test]
132	    fn save_and_load() {
133	        let temp = TempDir::new().unwrap();
134	        let path = temp.path().join("trusted_urls.yml");
135	
136	        let mut store = TrustStore::default();
137	        store.trust("https://example.com/base.yml");
138	        store.trust("https://corp.example.com/shared.yml");
139	        store.save(&path).unwrap();
140	
141	        let loaded = TrustStore::load(&path).unwrap();
142	        assert!(loaded.is_trusted("https://example.com/base.yml"));
143	        assert!(loaded.is_trusted("https://corp.example.com/shared.yml"));
144	        assert!(!loaded.is_trusted("https://other.com/config.yml"));
145	    }
146	
147	    #[test]
148	    fn load_nonexistent_returns_default() {
149	        let temp = TempDir::new().unwrap();
150	        let path = temp.path().join("nonexistent.yml");
151	
152	        let store = TrustStore::load(&path).unwrap();
153	        assert!(store.urls.is_empty());
154	    }
155	
156	    #[test]
157	    fn save_creates_parent_directories() {
158	        let temp = TempDir::new().unwrap();
159	        let path = temp.path().join("nested").join("dir").join("trusted.yml");
160	
161	        let mut store = TrustStore::default();
162	        store.trust("https://example.com/config.yml");
163	        store.save(&path).unwrap();
164	
165	        assert!(path.exists());
166	        let loaded = TrustStore::load(&path).unwrap();
167	        assert!(loaded.is_trusted("https://example.com/config.yml"));
168	    }
169	
170	    #[test]
171	    fn save_uses_atomic_write() {
172	        let temp = TempDir::new().unwrap();
173	        let path = temp.path().join("trusted_urls.yml");
174	
175	        let mut store = TrustStore::default();
176	        store.trust("https://example.com/config.yml");
177	        store.save(&path).unwrap();
178	
179	        // Temp file should not remain
180	        let temp_path = path.with_extension("yml.tmp");
181	        assert!(!temp_path.exists());
182	    }
183	
184	    #[test]
185	    fn trust_policy_variants() {
