        let args = InitArgs::default();
        let cmd = InitCommand::new(temp.path(), args);

        assert!(!cmd.config_exists());

        fs::write(bivvy_dir.join("config.yml"), "app_name: test").unwrap();
        assert!(cmd.config_exists());
